/** How a column sorts and aligns (sb-table.js): numbers and dates descending first, words ascending first. */
enum class SbColumnKind { Text, Number, Date }

/** A column: [title] the head's word, [kind] how it sorts (Number: end-aligned, tabular figures), [sortable] = a button. */
@Immutable
data class SbTableColumn(val title: String, val kind: SbColumnKind = SbColumnKind.Text, val sortable: Boolean = true)

/**
 * A cell: [text] as shown („1.250,00 €“, „01.10.“, „keine Angabe“); in a Number column [number], in a Date column
 * [date] is what it sorts by, null = no value (it sorts last in both directions, D82). A Text column sorts by [text];
 * a blank text has no value.
 */
@Immutable
data class SbTableCell(val text: String, val number: Double? = null, val date: LocalDate? = null)

/**
 * The sum row (D91 B6a): [label] („Summe“, „Summe der bekannten Stunden“) spans the columns before the first sum;
 * [values] maps a column index to its sum („1.797,20 €“). It stays at the bottom in every order.
 */
@Immutable
data class SbTableSum(val label: String, val values: Map<Int, String>)

/**
 * The order of [rows] by column [index] as sb-table.js sorts: numbers and dates by value, words with the collation of
 * [locale] (ICU, numeric, base letters), a cell without a value last in both directions, equal rows in their given
 * order. Returns the row indices in the new order.
 */
fun sbSortOrder(rows: List<List<SbTableCell>>, index: Int, kind: SbColumnKind, descending: Boolean, locale: Locale): List<Int> {
    val collator = Collator.getInstance(ULocale.forLocale(locale)).apply {
        strength = Collator.PRIMARY
        if (this is RuleBasedCollator) setNumericCollation(true)
    }
    val sign = if (descending) -1 else 1
    fun has(cell: SbTableCell?) = when (kind) {
        SbColumnKind.Number -> cell?.number != null
        SbColumnKind.Date -> cell?.date != null
        SbColumnKind.Text -> !cell?.text.isNullOrBlank()
    }
    return rows.indices.sortedWith { a, b ->
        val x = rows[a].getOrNull(index)
        val y = rows[b].getOrNull(index)
        when {
            !has(x) && !has(y) -> 0
            !has(x) -> 1
            !has(y) -> -1
            else -> sign * when (kind) {
                SbColumnKind.Number -> requireNotNull(x?.number).compareTo(requireNotNull(y?.number))
                SbColumnKind.Date -> requireNotNull(x?.date).compareTo(requireNotNull(y?.date))
                SbColumnKind.Text -> collator.compare(requireNotNull(x).text.trim(), requireNotNull(y).text.trim())
            }
        }
    }
}

/**
 * Sortable table (spec/02 §3.9, D91 B5a, B6a, D101 (3), (4)): [caption] above it (caption textMuted, and the name of
 * the frame for TalkBack), the heads of [columns] (label; a sortable head a 48 dp button with 8 dp of ground beyond its
 * word, hover and pressed fills, the focus ring; the sorted one in the title weight with the 16 dp arrow, before the
 * word in a number column), a borderStrong line under them, then [rows] (body; [rowHeads] = the first cell in
 * bodyStrong; numbers end-aligned with tabular figures; 12 dp around, a border hairline under each row), then [sum].
 * The wrapper sorts the rows by [sortIndex] (-1 = the order given) and [sortDescending]; a press calls [onSort] with
 * the new column and direction (the same head turns round; another sorts numbers and dates descending, words
 * ascending first) and the app keeps them. Columns take their text's width; when the widest words do not fit, the table
 * scrolls sideways inside its own frame (8 dp of room at both sides), never the screen; ← / → scroll it by 40 dp.
 * TalkBack: a table of rows and columns; the sorted head's state is „Sortiert nach <Spalte>, absteigend“ (the head's
 * state instead of the web's status line: provisional, agent). It measures its columns from its width (a
 * BoxWithConstraints), so it cannot stand in a parent that asks for intrinsic sizes (spec/08 §17).
 */
@Composable
fun SbSortableTable(
    caption: String,
    columns: List<SbTableColumn>,
    rows: List<List<SbTableCell>>,
    sortIndex: Int,
    sortDescending: Boolean,
    onSort: (index: Int, descending: Boolean) -> Unit,
    modifier: Modifier = Modifier,
    rowHeads: Boolean = false,
    sum: SbTableSum? = null,
) {
    require(columns.isNotEmpty()) { "SbSortableTable: no columns" }
    require(rows.all { it.size == columns.size }) { "SbSortableTable: one cell per column in every row" }
    require(sortIndex in -1..columns.lastIndex) { "SbSortableTable: sortIndex out of range" }
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val m = sbMessages()
    val locale = sbAppLocale()
    val order = remember(rows, sortIndex, sortDescending, locale) {
        if (sortIndex < 0) rows.indices.toList()
        else sbSortOrder(rows, sortIndex, columns[sortIndex].kind, sortDescending, locale)
    }
    val numeric = ty.body.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    val strongNumeric = ty.bodyStrong.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    val headStyle = ty.label.copy(fontWeight = ty.title.fontWeight)
    fun cellStyle(col: Int, row: Boolean) = when {
        row && col == 0 && rowHeads -> ty.bodyStrong
        columns[col].kind == SbColumnKind.Number -> numeric
        else -> ty.body
    }
    val measurer = rememberTextMeasurer()
    val scroller = rememberScrollState()
    val interaction = remember { MutableInteractionSource() }
    Column(modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(t.space.s2)) {
        // the frame below carries the caption as its name, so TalkBack hears it once
        Text(caption, style = ty.caption, color = c.textMuted, modifier = Modifier.clearAndSetSemantics { })
        BoxWithConstraints(Modifier.fillMaxWidth()) {
            val density = LocalDensity.current
            val room = t.space.s2   // the heads' ground beyond the table at both sides (the web's wrap)
            val gap = with(density) { t.space.s3.roundToPx() }
            val arrow = with(density) { (t.size.iconSm + t.space.s1).roundToPx() }
            // the narrowest and the widest width of each column's text: its widest word and its widest single line
            // keyed on the styles too: the dark theme's heavier weights need wider columns (a value joined by U+00A0
            // must not split when the theme changes in place)
            val widths = remember(columns, rows, sum, rowHeads, constraints.maxWidth, density, ty, locale) {
                fun span(text: String, style: TextStyle): Pair<Int, Int> {
                    val r = measurer.measure(text, style)
                    return ceil(r.multiParagraph.intrinsics.minIntrinsicWidth).toInt() to ceil(r.multiParagraph.intrinsics.maxIntrinsicWidth).toInt()
                }
                val low = IntArray(columns.size)
                val high = IntArray(columns.size)
                columns.forEachIndexed { i, col ->
                    val (a, b) = span(col.title, if (col.sortable) headStyle else ty.label)
                    val extra = if (col.sortable) arrow else 0
                    low[i] = a + extra
                    high[i] = b + extra
                    rows.forEach { row ->
                        val (x, y) = span(row[i].text, cellStyle(i, true))
                        low[i] = maxOf(low[i], x)
                        high[i] = maxOf(high[i], y)
                    }
                    sum?.values?.get(i)?.let { v ->
                        val (x, y) = span(v, if (col.kind == SbColumnKind.Number) strongNumeric else ty.bodyStrong)
                        low[i] = maxOf(low[i], x)
                        high[i] = maxOf(high[i], y)
                    }
                }
                // the sum row's label spans the columns before the first sum: they hold it together, the first takes
                // what they lack (the web's colspan)
                sum?.let { foot ->
                    val first = (foot.values.keys.minOrNull() ?: columns.size).coerceAtMost(columns.size)
                    if (first > 0) {
                        val (x, y) = span(foot.label, ty.bodyStrong)
                        val gaps = gap * (first - 1)
                        low[0] += maxOf(0, x - gaps - (0 until first).sumOf { low[it] })
                        high[0] += maxOf(0, y - gaps - (0 until first).sumOf { high[it] })
                    }
                }
                // the padding after each column but the last
                for (i in 0 until columns.lastIndex) {
                    low[i] += gap
                    high[i] += gap
                }
                val avail = constraints.maxWidth
                val lowSum = low.sum()
                val highSum = high.sum()
                IntArray(columns.size) { i ->
                    when {
                        highSum <= avail -> high[i] + (avail - highSum) * high[i] / maxOf(highSum, 1)
                        lowSum < avail -> low[i] + (avail - lowSum) * (high[i] - low[i]) / maxOf(highSum - lowSum, 1)
                        else -> low[i]
                    }
                }
            }
            val step = with(density) { t.space.s10.toPx() }   // 40 dp for each arrow, as the code area
            Box(
                Modifier
                    .sbLayout { measurable, outer ->
                        // the frame reaches 8 dp beyond the table at both sides, as the web's wrap
                        val extra = (room * 2).roundToPx()
                        val p = measurable.measure(outer.copy(minWidth = outer.minWidth + extra, maxWidth = outer.maxWidth + extra))
                        layout(outer.maxWidth, p.height) { p.placeRelative(-room.roundToPx(), 0) }
                    }
                    .sbFocusRingInset(interaction)
                    .onPreviewKeyEvent { e ->
                        if (e.type != KeyEventType.KeyDown) return@onPreviewKeyEvent false
                        val delta = when (e.key) {
                            Key.DirectionRight -> step
                            Key.DirectionLeft -> -step
                            else -> return@onPreviewKeyEvent false
                        }
                        scroller.dispatchRawDelta(delta) != 0f
                    }
                    .semantics {
                        contentDescription = caption
                        collectionInfo = CollectionInfo(rowCount = rows.size + 1 + (if (sum != null) 1 else 0), columnCount = columns.size)
                    }
                    .focusable(interactionSource = interaction)
                    .horizontalScroll(scroller)
                    .padding(horizontal = room),
            ) {
                Column {
                    SbTableHead(columns, widths, sortIndex, sortDescending, headStyle, onSort, m)
                    order.forEachIndexed { at, r ->
                        val last = at == order.lastIndex
                        SbTableRow(
                            line = if (last && sum != null) c.borderStrong else c.border,
                        ) {
                            rows[r].forEachIndexed { i, cell ->
                                SbTableBox(widths[i], i == columns.lastIndex, at + 1, i) {
                                    Text(
                                        cell.text,
                                        style = cellStyle(i, true),
                                        color = c.text,
                                        textAlign = if (columns[i].kind == SbColumnKind.Number) TextAlign.End else TextAlign.Start,
                                        modifier = Modifier.fillMaxWidth(),
                                    )
                                }
                            }
                        }
                    }
                    sum?.let { foot ->
                        val first = foot.values.keys.minOrNull() ?: columns.size
                        SbTableRow(line = null) {
                            if (first > 0) {
                                SbTableBox((0 until first).sumOf { widths[it] }, first == columns.size, order.size + 1, 0, span = first) {
                                    Text(foot.label, style = ty.bodyStrong, color = c.text)
                                }
                            }
                            for (i in first until columns.size) {
                                SbTableBox(widths[i], i == columns.lastIndex, order.size + 1, i) {
                                    Text(
                                        foot.values[i] ?: "",
                                        style = if (columns[i].kind == SbColumnKind.Number) strongNumeric else ty.bodyStrong,
                                        color = c.text,
                                        textAlign = if (columns[i].kind == SbColumnKind.Number) TextAlign.End else TextAlign.Start,
                                        modifier = Modifier.fillMaxWidth(),
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

/** A row of the table: its cells side by side, aligned to the top, with [line] (null = none) under it. */
@Composable
private fun SbTableRow(line: Color?, content: @Composable () -> Unit) {
    val hair = SebaroTheme.tokens.borderWidth.hairline
    Row(
        Modifier.drawBehind {
            if (line != null) drawRect(line, Offset(0f, size.height - hair.toPx()), Size(size.width, hair.toPx()))
        },
        verticalAlignment = Alignment.Top,
    ) { content() }
}

/** One cell [width] px wide: 12 dp above and below, 12 dp after it unless [last]; its row and column for TalkBack. */
@Composable
private fun SbTableBox(width: Int, last: Boolean, row: Int, column: Int, span: Int = 1, content: @Composable () -> Unit) {
    val t = SebaroTheme.tokens
    Box(
        Modifier
            .width(with(LocalDensity.current) { width.toDp() })
            .semantics(mergeDescendants = true) { collectionItemInfo = CollectionItemInfo(row, 1, column, span) }
            .padding(top = t.space.s3, bottom = t.space.s3, end = if (last) t.space.s0 else t.space.s3),
    ) { content() }
}

/** The head row: a sortable head is a 48 dp button; the sorted one has the title weight, the arrow and its state. */
@Composable
private fun SbTableHead(
    columns: List<SbTableColumn>,
    widths: IntArray,
    sortIndex: Int,
    sortDescending: Boolean,
    headStyle: TextStyle,
    onSort: (Int, Boolean) -> Unit,
    m: SbMessages,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    SbTableRow(line = c.borderStrong) {
        columns.forEachIndexed { i, col ->
            val last = i == columns.lastIndex
            val number = col.kind == SbColumnKind.Number
            Box(
                Modifier
                    .width(with(LocalDensity.current) { widths[i].toDp() })
                    .padding(top = t.space.s1, bottom = t.space.s1, end = if (last) t.space.s0 else t.space.s3),
                contentAlignment = if (number) Alignment.BottomEnd else Alignment.BottomStart,
            ) {
                if (!col.sortable) {
                    Text(
                        col.title,
                        style = ty.label,
                        color = c.text,
                        modifier = Modifier
                            .semantics { collectionItemInfo = CollectionItemInfo(0, 1, i, 1) }
                            .padding(vertical = t.space.s3),
                    )
                    return@Box
                }
                val sorted = i == sortIndex
                val interaction = remember { MutableInteractionSource() }
                val pressed by interaction.collectIsPressedAsState()
                val hovered by interaction.collectIsHoveredAsState()
                val fill = when {
                    pressed -> c.pressedFill
                    hovered -> c.hoverFill
                    else -> Color.Transparent
                }
                val arrow: @Composable () -> Unit = {
                    if (sorted) {
                        Icon(
                            if (sortDescending) SebaroIcons.Outline16.ArrowDown else SebaroIcons.Outline16.ArrowUp,
                            contentDescription = null,
                            tint = c.text,
                            modifier = Modifier.size(t.size.iconSm),
                        )
                    }
                }
                Row(
                    Modifier
                        // 8 dp of ground beyond the word at both sides, the word stays in line with its column
                        .sbLayout { measurable, outer ->
                            val extra = (t.space.s2 * 2).roundToPx()
                            val p = measurable.measure(outer.copy(minWidth = 0, maxWidth = outer.maxWidth + extra))
                            layout(p.width - extra, p.height) { p.placeRelative(-t.space.s2.roundToPx(), 0) }
                        }
                        .sbFocusRing(interaction, t.radius.control)
                        .heightIn(min = t.size.targetTouch)
                        .background(fill, t.shapes.control)
                        .semantics {
                            collectionItemInfo = CollectionItemInfo(0, 1, i, 1)
                            if (sorted) stateDescription = m.tableSorted(col.title, sortDescending)
                        }
                        .clickable(interactionSource = interaction, indication = null, role = Role.Button) {
                            onSort(i, if (sorted) !sortDescending else col.kind != SbColumnKind.Text)
                        }
                        .padding(horizontal = t.space.s2),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(t.space.s1),
                ) {
                    if (number) arrow()
                    Text(col.title, style = if (sorted) headStyle else ty.label, color = c.text)
                    if (!number) arrow()
                }
            }
        }
    }
}
